Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI, -apple-system, BlinkMacSystemFont, sans-serif",
    "padding": {
      "top": 10,
      "left": 10,
      "right": 20,
      "bottom": 15
    }
  },
  "transform": [
    {
      "filter": "datum[''Chapter ID''] != null && datum[''Chapter ID''] >= 1 && datum[''Chapter ID''] <= 5"
    },
    {
      "calculate": "datum[''Selected Time Mode ID''] != null ? datum[''Selected Time Mode ID''] : 1",
      "as": "mode_id"
    },
    {
      "calculate": "datum.mode_id == 4 || datum.mode_id == 5 ? datum[''Time Mode Value''] : (datum.mode_id == 6 ? datum[''Time Mode Value''] : datum[''Dynamic Selected Metric''])",
      "as": "primary_val"
    },
    {
      "calculate": "datum.mode_id == 2 || datum.mode_id == 3 ? datum[''Time Mode Value''] : (datum.mode_id == 6 ? datum[''Dynamic Selected Metric''] : null)",
      "as": "secondary_val"
    },
    {
      "calculate": "datum.mode_id == 6 ? ''Rolling avg'' : (datum.mode_id == 4 ? ''YoY Variance'' : (datum.mode_id == 5 ? ''YoY Variance %'' : ''Current''))",
      "as": "primary_label"
    },
    {
      "calculate": "datum.mode_id == 2 ? ''Previous period'' : (datum.mode_id == 3 ? ''Previous year'' : (datum.mode_id == 6 ? ''Monthly'' : null))",
      "as": "secondary_label"
    },
    {
      "calculate": "datum.mode_id == 5 ? format(datum.primary_val, ''+0.1%'') : (datum[''Selected Metric ID''] == 4 || datum[''Selected Metric ID''] == 7 || datum[''Selected Metric ID''] == 9 || datum[''Selected Metric ID''] == 10 ? format(datum.primary_val, ''0.00%'') : (datum[''Selected Metric ID''] == 5 || datum[''Selected Metric ID''] == 6 ? format(datum.primary_val, '',.0f'') : (''$'' + format(datum.primary_val, '',.2f''))))",
      "as": "primary_val_formatted"
    },
    {
      "calculate": "datum.secondary_val != null ? (datum[''Selected Metric ID''] == 4 || datum[''Selected Metric ID''] == 7 || datum[''Selected Metric ID''] == 9 || datum[''Selected Metric ID''] == 10 ? format(datum.secondary_val, ''0.00%'') : (datum[''Selected Metric ID''] == 5 || datum[''Selected Metric ID''] == 6 ? format(datum.secondary_val, '',.0f'') : (''$'' + format(datum.secondary_val, '',.2f'')))) : ''''",
      "as": "secondary_val_formatted"
    }
  ],
  "layer": [
    {
      "name": "chapter_bands",
      "transform": [
        {
          "aggregate": [
            {
              "op": "min",
              "field": "Month Start",
              "as": "band_start"
            },
            {
              "op": "max",
              "field": "Month Start",
              "as": "band_max"
            },
            {
              "op": "max",
              "field": "Is Selected Chapter",
              "as": "is_sel"
            }
          ],
          "groupby": [
            "Chapter Name",
            "Chapter Color",
            "Chapter ID"
          ]
        },
        {
          "calculate": "timeOffset(''month'', datum.band_max, 1)",
          "as": "band_end"
        }
      ],
      "mark": {
        "type": "rect"
      },
      "encoding": {
        "x": {
          "field": "band_start",
          "type": "temporal"
        },
        "x2": {
          "field": "band_end"
        },
        "color": {
          "field": "Chapter Color",
          "type": "nominal",
          "scale": null
        },
        "opacity": {
          "condition": [
            {
              "test": "datum.is_sel == 1",
              "value": 0.8
            },
            {
              "test": "datum.is_sel == 2",
              "value": 0.28
            }
          ],
          "value": 0.18
        }
      }
    },
    {
      "name": "primary_area",
      "transform": [
        {
          "filter": "datum.primary_val != null && isValid(datum.primary_val)"
        }
      ],
      "mark": {
        "type": "area",
        "interpolate": "monotone",
        "line": false,
        "color": {
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "rgba(29, 78, 216, 0.20)"
            },
            {
              "offset": 1,
              "color": "rgba(29, 78, 216, 0.01)"
            }
          ],
          "x1": 0,
          "y1": 0,
          "x2": 0,
          "y2": 1
        }
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal",
          "axis": {
            "title": null,
            "format": "%b ''%y",
            "labelColor": "#475569",
            "labelFontSize": 10,
            "tickColor": "#E2E8F0",
            "domainColor": "#E2E8F0",
            "grid": false
          }
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative",
          "axis": {
            "title": null,
            "labelColor": "#475569",
            "labelFontSize": 10,
            "tickColor": "transparent",
            "domain": false,
            "gridColor": "#E2E8F0",
            "gridDash": [
              3,
              3
            ],
            "labelExpr": "data(''dataset'') && data(''dataset'')[0] && data(''dataset'')[0][''Selected Time Mode ID''] == 5 ? (datum.value == 0 ? ''0%'' : (datum.value > 0 ? ''+'' : '''') + format(datum.value, ''.0%'')) : (data(''dataset'') && data(''dataset'')[0] && data(''dataset'')[0][''Selected Time Mode ID''] == 4 ? (data(''dataset'')[0][''Selected Metric ID''] == 4 || data(''dataset'')[0][''Selected Metric ID''] == 7 || data(''dataset'')[0][''Selected Metric ID''] == 9 || data(''dataset'')[0][''Selected Metric ID''] == 10 ? (datum.value == 0 ? ''0%'' : (datum.value > 0 ? ''+'' : '''') + format(datum.value, ''.1%'')) : (data(''dataset'')[0][''Selected Metric ID''] == 5 || data(''dataset'')[0][''Selected Metric ID''] == 6 ? (datum.value == 0 ? ''0'' : (datum.value > 0 ? ''+'' : ''-'') + replace(format(abs(datum.value), ''~s''), ''k'', ''K'')) : (datum.value == 0 ? ''$0'' : (datum.value > 0 ? ''+$'' : ''-$'') + replace(format(abs(datum.value), ''~s''), ''k'', ''K'')))) : (data(''dataset'') && data(''dataset'')[0] && (data(''dataset'')[0][''Selected Metric ID''] == 4 || data(''dataset'')[0][''Selected Metric ID''] == 7 || data(''dataset'')[0][''Selected Metric ID''] == 9 || data(''dataset'')[0][''Selected Metric ID''] == 10) ? (datum.value == 0 ? ''0%'' : (datum.value < 0.2 ? format(datum.value, ''.1%'') : format(datum.value, ''.0%''))) : (data(''dataset'') && data(''dataset'')[0] && (data(''dataset'')[0][''Selected Metric ID''] == 5 || data(''dataset'')[0][''Selected Metric ID''] == 6) ? replace(format(datum.value, ''~s''), ''k'', ''K'') : (domain(''y'')[1] <= 1 && domain(''y'')[0] >= -1 ? (datum.value == 0 ? ''0%'' : format(datum.value, ''.0%'')) : (domain(''y'')[1] < 150 ? (''$'' + format(datum.value, ''.0f'')) : (datum.value < 0 ? (''-$'' + replace(format(abs(datum.value), ''~s''), ''k'', ''K'')) : (''$'' + replace(format(datum.value, ''~s''), ''k'', ''K''))))))))"
          }
        }
      }
    },
    {
      "name": "secondary_line",
      "transform": [
        {
          "filter": "datum.secondary_val != null && isValid(datum.secondary_val)"
        }
      ],
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "strokeWidth": 2,
        "strokeDash": [
          4,
          4
        ],
        "strokeCap": "round"
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "secondary_val",
          "type": "quantitative"
        },
        "color": {
          "field": "secondary_label",
          "type": "nominal",
          "scale": {
            "domain": [
              "Current",
              "Rolling avg",
              "YoY Variance",
              "YoY Variance %",
              "Previous period",
              "Previous year",
              "Monthly"
            ],
            "range": [
              "#1D4ED8",
              "#1D4ED8",
              "#1D4ED8",
              "#1D4ED8",
              "#64748B",
              "#D97706",
              "#64748B"
            ]
          },
          "legend": null
        }
      }
    },
    {
      "name": "primary_line",
      "transform": [
        {
          "filter": "datum.primary_val != null && isValid(datum.primary_val)"
        }
      ],
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "strokeWidth": 2,
        "strokeCap": "round",
        "strokeJoin": "round"
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative"
        },
        "color": {
          "field": "primary_label",
          "type": "nominal",
          "scale": {
            "domain": [
              "Current",
              "Rolling avg",
              "YoY Variance",
              "YoY Variance %",
              "Previous period",
              "Previous year",
              "Monthly"
            ],
            "range": [
              "#1D4ED8",
              "#1D4ED8",
              "#1D4ED8",
              "#1D4ED8",
              "#64748B",
              "#D97706",
              "#64748B"
            ]
          },
          "legend": null
        }
      }
    },
    {
      "name": "spotlight_mask",
      "transform": [
        {
          "aggregate": [
            {
              "op": "min",
              "field": "Month Start",
              "as": "band_start"
            },
            {
              "op": "max",
              "field": "Month Start",
              "as": "band_max"
            },
            {
              "op": "max",
              "field": "Is Selected Chapter",
              "as": "is_sel"
            }
          ],
          "groupby": [
            "Chapter Name",
            "Chapter ID"
          ]
        },
        {
          "filter": "datum.is_sel == 0"
        },
        {
          "calculate": "timeOffset(''month'', datum.band_max, 1)",
          "as": "band_end"
        }
      ],
      "mark": {
        "type": "rect",
        "color": "#FFFFFF",
        "opacity": 0.6
      },
      "encoding": {
        "x": {
          "field": "band_start",
          "type": "temporal"
        },
        "x2": {
          "field": "band_end"
        }
      }
    },
    {
      "name": "selected_area",
      "transform": [
        {
          "filter": "datum[''Is Selected Chapter''] == 1 && datum.primary_val != null && isValid(datum.primary_val)"
        }
      ],
      "mark": {
        "type": "area",
        "interpolate": "monotone",
        "line": false,
        "color": {
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "rgba(29, 78, 216, 0.38)"
            },
            {
              "offset": 1,
              "color": "rgba(29, 78, 216, 0.04)"
            }
          ],
          "x1": 0,
          "y1": 0,
          "x2": 0,
          "y2": 1
        }
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative"
        }
      }
    },
    {
      "name": "selected_glow",
      "transform": [
        {
          "filter": "datum[''Is Selected Chapter''] == 1 && datum.primary_val != null && isValid(datum.primary_val)"
        }
      ],
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "strokeWidth": 10,
        "stroke": "#1D4ED8",
        "opacity": 0.16,
        "strokeCap": "round"
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative"
        }
      }
    },
    {
      "name": "selected_line",
      "transform": [
        {
          "filter": "datum[''Is Selected Chapter''] == 1 && datum.primary_val != null && isValid(datum.primary_val)"
        }
      ],
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "strokeWidth": 3.75,
        "stroke": "#1D4ED8",
        "strokeCap": "round",
        "strokeJoin": "round"
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative"
        }
      }
    },
    {
      "name": "selected_outline",
      "transform": [
        {
          "aggregate": [
            {
              "op": "min",
              "field": "Month Start",
              "as": "band_start"
            },
            {
              "op": "max",
              "field": "Month Start",
              "as": "band_max"
            },
            {
              "op": "max",
              "field": "Is Selected Chapter",
              "as": "is_sel"
            }
          ],
          "groupby": [
            "Chapter Name",
            "Chapter ID"
          ]
        },
        {
          "filter": "datum.is_sel == 1"
        },
        {
          "calculate": "timeOffset(''month'', datum.band_max, 1)",
          "as": "band_end"
        }
      ],
      "mark": {
        "type": "rect",
        "fill": null,
        "stroke": "#0D9488",
        "strokeWidth": 1.75,
        "strokeDash": [
          5,
          3
        ],
        "opacity": 0.9
      },
      "encoding": {
        "x": {
          "field": "band_start",
          "type": "temporal"
        },
        "x2": {
          "field": "band_end"
        }
      }
    },
    {
      "name": "selected_header_bar",
      "transform": [
        {
          "aggregate": [
            {
              "op": "min",
              "field": "Month Start",
              "as": "band_start"
            },
            {
              "op": "max",
              "field": "Month Start",
              "as": "band_max"
            },
            {
              "op": "max",
              "field": "Is Selected Chapter",
              "as": "is_sel"
            }
          ],
          "groupby": [
            "Chapter Name",
            "Chapter ID"
          ]
        },
        {
          "filter": "datum.is_sel == 1"
        },
        {
          "calculate": "timeOffset(''month'', datum.band_max, 1)",
          "as": "band_end"
        }
      ],
      "mark": {
        "type": "rect",
        "color": "#0D9488"
      },
      "encoding": {
        "x": {
          "field": "band_start",
          "type": "temporal"
        },
        "x2": {
          "field": "band_end"
        },
        "y": {
          "value": 0
        },
        "y2": {
          "value": 5
        }
      }
    },
    {
      "name": "secondary_points",
      "transform": [
        {
          "filter": "datum.secondary_val != null && isValid(datum.secondary_val)"
        }
      ],
      "mark": {
        "type": "circle",
        "size": 24
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "secondary_val",
          "type": "quantitative"
        },
        "color": {
          "field": "secondary_label",
          "type": "nominal",
          "scale": {
            "domain": [
              "Current",
              "Rolling avg",
              "YoY Variance",
              "YoY Variance %",
              "Previous period",
              "Previous year",
              "Monthly"
            ],
            "range": [
              "#1D4ED8",
              "#1D4ED8",
              "#1D4ED8",
              "#1D4ED8",
              "#64748B",
              "#D97706",
              "#64748B"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "Month Start",
            "type": "temporal",
            "format": "%B %Y",
            "title": "Month"
          },
          {
            "field": "secondary_label",
            "type": "nominal",
            "title": "Series"
          },
          {
            "field": "secondary_val_formatted",
            "type": "nominal",
            "title": "Value"
          }
        ]
      }
    },
    {
      "name": "primary_points",
      "transform": [
        {
          "filter": "datum.primary_val != null && isValid(datum.primary_val)"
        }
      ],
      "mark": {
        "type": "circle",
        "color": "#1D4ED8",
        "fill": "#FFFFFF",
        "stroke": "#1D4ED8",
        "strokeWidth": 2
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative"
        },
        "size": {
          "condition": [
            {
              "test": "datum[''Is Selected Chapter''] == 1",
              "value": 70
            },
            {
              "test": "datum[''Is Selected Chapter''] == 2",
              "value": 38
            }
          ],
          "value": 22
        },
        "opacity": {
          "condition": [
            {
              "test": "datum[''Is Selected Chapter''] == 1",
              "value": 1.0
            },
            {
              "test": "datum[''Is Selected Chapter''] == 2",
              "value": 0.85
            }
          ],
          "value": 0.2
        },
        "tooltip": [
          {
            "field": "Month Start",
            "type": "temporal",
            "format": "%B %Y",
            "title": "Month"
          },
          {
            "field": "Chapter Name",
            "type": "nominal",
            "title": "Chapter"
          },
          {
            "field": "primary_label",
            "type": "nominal",
            "title": "Series"
          },
          {
            "field": "primary_val_formatted",
            "type": "nominal",
            "title": "Value"
          }
        ]
      }
    },
    {
      "name": "peak_ring",
      "transform": [
        {
          "filter": "datum[''Is Selected Chapter''] == 1 && datum.primary_val != null && isValid(datum.primary_val)"
        },
        {
          "joinaggregate": [
            {
              "op": "max",
              "field": "primary_val",
              "as": "pk"
            }
          ]
        },
        {
          "filter": "datum.primary_val == datum.pk"
        }
      ],
      "mark": {
        "type": "circle",
        "size": 190,
        "fill": "#FFFFFF",
        "stroke": "#D97706",
        "strokeWidth": 2.75
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative"
        }
      }
    },
    {
      "name": "peak_label",
      "transform": [
        {
          "filter": "datum[''Is Selected Chapter''] == 1 && datum.primary_val != null && isValid(datum.primary_val)"
        },
        {
          "joinaggregate": [
            {
              "op": "max",
              "field": "primary_val",
              "as": "pk"
            }
          ]
        },
        {
          "filter": "datum.primary_val == datum.pk"
        }
      ],
      "mark": {
        "type": "text",
        "dy": 22,
        "fontSize": 11,
        "fontWeight": 800,
        "color": "#B45309"
      },
      "encoding": {
        "x": {
          "field": "Month Start",
          "type": "temporal"
        },
        "y": {
          "field": "primary_val",
          "type": "quantitative"
        },
        "text": {
          "field": "primary_val_formatted"
        }
      }
    },
    {
      "name": "chapter_labels",
      "transform": [
        {
          "aggregate": [
            {
              "op": "min",
              "field": "Month Start",
              "as": "band_start"
            },
            {
              "op": "max",
              "field": "Month Start",
              "as": "band_max"
            },
            {
              "op": "max",
              "field": "Is Selected Chapter",
              "as": "is_sel"
            }
          ],
          "groupby": [
            "Chapter Name",
            "Chapter Color",
            "Chapter ID"
          ]
        },
        {
          "calculate": "toDate((time(datum.band_start) + time(datum.band_max)) / 2)",
          "as": "mid_date"
        },
        {
          "calculate": "datum.is_sel == 1 ? ''\u25cf '' + datum[''Chapter Name''] : datum[''Chapter Name'']",
          "as": "label_txt"
        }
      ],
      "mark": {
        "type": "text",
        "y": 16,
        "fontWeight": 700,
        "baseline": "top"
      },
      "encoding": {
        "x": {
          "field": "mid_date",
          "type": "temporal"
        },
        "text": {
          "field": "label_txt"
        },
        "color": {
          "condition": [
            {
              "test": "datum.is_sel == 1",
              "value": "#0F766E"
            }
          ],
          "value": "#334155"
        },
        "fontSize": {
          "condition": [
            {
              "test": "datum.is_sel == 1",
              "value": 14
            }
          ],
          "value": 11
        },
        "opacity": {
          "condition": [
            {
              "test": "datum.is_sel == 1",
              "value": 1.0
            },
            {
              "test": "datum.is_sel == 2",
              "value": 0.95
            }
          ],
          "value": 0.55
        }
      }
    }
  ]
}'
